/* Baskı Hesabı — görünüm.
   Renkler ve katman çizgisi motifi önceki sürümlerden gelir; tanıdık kalsın diye korundu. */

:root{
  /* Yüzey ve metin renkleri ortak çekirdeğin tokenlarından gelir (falcon varsayılan, şema seçici, açık/koyu).
     Eski renkler "klasik" şeması olarak js/kabuk.js'te kayıtlıdır. Aşağıdakiler yalnız bu uygulamanın adlarıdır. */
  --panel2:var(--panel-hover); --field:var(--panel-hover);
  --line:var(--border); --line2:var(--border-strong);
  --ink:var(--text); --faint:var(--nav-title);
  --bad:var(--danger);

  /* maliyet kalemlerinin veri renkleri (grafik, yığın, lejant) — şemadan bağımsız */
  --filament:#45C8BE; --power:#6C9BF0; --labor:#A78BFA;
  --wear:#F0876A; --fail:#D96A8A; --profit:#F0B440;

  --r:var(--radius-md,10px); --r-s:var(--radius-sm,8px);
  --gut:18px;
}

*{box-sizing:border-box}
html,body{margin:0;padding:0;height:100%}
body{
  color:var(--ink);
  font-family:var(--font-ui);
  font-variant-numeric:tabular-nums;
  -webkit-font-smoothing:antialiased;
  font-size:calc(15px * var(--font-scale,1));line-height:1.45;
  overflow-x:hidden;
}
[dir=rtl] body{font-family:var(--font-ar)}

#app{min-height:100%;display:flex;flex-direction:column}

/* ---------- üst çubuk ---------- */
.topbar{
  padding:8px var(--gut);gap:12px;
  position:sticky;top:0;z-index:30;
}
html[dir=rtl] .topbar{padding:8px var(--gut)}
.bh-brand{display:flex;align-items:center;gap:11px;min-width:0}
.mark{display:flex;flex-direction:column-reverse;gap:2px;width:20px;flex:none}
.mark i{height:3px;border-radius:1px;display:block}
.mark i:nth-child(1){background:var(--filament)}
.mark i:nth-child(2){background:var(--power)}
.mark i:nth-child(3){background:var(--labor)}
.mark i:nth-child(4){background:var(--profit)}
.brand-txt{display:flex;align-items:baseline;gap:7px;min-width:0}
.brand-txt b{font-size:calc(16px * var(--font-scale,1));font-weight:600;letter-spacing:-.01em;white-space:nowrap}
.brand-txt em{font-style:normal;font-size:calc(12px * var(--font-scale,1));color:var(--faint)}
.topright{display:flex;align-items:center;gap:10px;flex:0 1 auto;min-width:0}

select,input,textarea,button{font:inherit;color:var(--ink)}

/* ---------- sekmeler ---------- */
.tabs{
  display:flex;gap:2px;padding:0 var(--gut);border-bottom:1px solid var(--line);
  overflow-x:auto;scrollbar-width:none;position:sticky;top:var(--bh-top,57px);z-index:29;
  background:var(--topbar-bg);backdrop-filter:blur(10px);
}
.tabs::-webkit-scrollbar{display:none}
.tabs button{
  background:none;border:0;border-bottom:2px solid transparent;
  padding:11px 14px;cursor:pointer;color:var(--muted);font-size:calc(14.5px * var(--font-scale,1));
  white-space:nowrap;transition:color .12s,border-color .12s;
}
.tabs button:hover{color:var(--ink)}
.tabs button.on{color:var(--ink);border-bottom-color:var(--accent)}

main{flex:1;padding:22px var(--gut) 60px;max-width:1480px;width:100%;margin:0 auto}

/* ---------- ortak parçalar ---------- */
h1{font-size:calc(21px * var(--font-scale,1));font-weight:600;letter-spacing:-.015em;margin:0 0 4px}
h2{font-size:calc(15px * var(--font-scale,1));font-weight:600;margin:0 0 12px}
h3{font-size:calc(15px * var(--font-scale,1));font-weight:600;margin:0}
.lead{color:var(--muted);font-size:calc(14px * var(--font-scale,1));margin:0 0 20px;max-width:70ch}

.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:18px}
.panel + .panel{margin-top:14px}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;align-items:start}
.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;align-items:start}
.sticky{position:sticky;top:106px}

.sec{font-size:calc(13px * var(--font-scale,1));color:var(--muted);margin:18px 0 2px}
.sec:first-child{margin-top:0}

.field{margin-top:11px}
.field:first-child{margin-top:0}
label{display:block;font-size:calc(14px * var(--font-scale,1));margin-bottom:5px}
.hint{color:var(--muted);font-size:calc(13px * var(--font-scale,1));font-weight:400}
.sub{margin:7px 0 0;font-size:calc(13px * var(--font-scale,1));color:var(--muted)}
.sub b{color:var(--power);font-weight:600}

.inp{display:flex;align-items:center;gap:8px;background:var(--field);
  border:1px solid var(--line);border-radius:var(--r-s);padding:0 11px}
.inp:focus-within{outline:var(--focus-w) solid var(--focus);outline-offset:1px;border-color:var(--focus)}
.inp span{color:var(--muted);font-size:calc(13px * var(--font-scale,1));flex:none}
.inp input,.inp select,.inp textarea{
  width:100%;background:none;border:0;outline:none;font-size:calc(15px * var(--font-scale,1));padding:9px 0;
}
.inp select{cursor:pointer;margin-inline-end:-4px}
.inp select option{background:var(--panel2)}
.inp textarea{resize:vertical;min-height:64px;padding:9px 0}
input[type=number]::-webkit-outer-spin-button,
input[type=number]::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
input[type=number]{-moz-appearance:textfield}

.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.pair3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}

/* onay kutusu */
.chk{display:flex;align-items:center;gap:9px;cursor:pointer;user-select:none;font-size:calc(14px * var(--font-scale,1))}
.chk.head{margin-top:18px;font-weight:600}
.chk input{appearance:none;-webkit-appearance:none;width:17px;height:17px;flex:none;
  border:1px solid var(--line2);border-radius:4px;background:var(--field);cursor:pointer;
  display:grid;place-content:center;transition:background-color .12s,border-color .12s}
.chk input::after{content:"";width:9px;height:9px;background:var(--bg);transform:scale(0);
  transition:transform .1s;clip-path:polygon(14% 46%,0 60%,39% 100%,100% 22%,86% 8%,39% 72%)}
.chk input:checked{background:var(--acc,var(--accent));border-color:var(--acc,var(--accent))}
.chk input:checked::after{transform:scale(1)}
.chk input:focus-visible{outline:var(--focus-w) solid var(--focus);outline-offset:2px}
.group{padding-inline-start:26px}
.group.off{opacity:.42;pointer-events:none}

/* düğmeler */
button.btn{background:var(--field);border:1px solid var(--line);border-radius:var(--r-s);
  padding:9px 15px;cursor:pointer;font-size:calc(14px * var(--font-scale,1));transition:background-color .12s,border-color .12s}
button.btn:hover:not(:disabled){background:var(--line)}
button.btn:disabled{opacity:.5;cursor:default}
button.btn.pri{background:var(--grad-primary);border-color:transparent;color:var(--on-accent);font-weight:600}
button.btn.pri:hover:not(:disabled){filter:brightness(1.08);background:var(--grad-primary)}
button.btn.danger{background:var(--danger-soft);color:var(--danger-text);border-color:var(--danger-line)}
button.btn.danger:hover:not(:disabled){filter:brightness(1.15);background:var(--danger-soft)}
button.btn:focus-visible{outline:var(--focus-w) solid var(--focus);outline-offset:2px}
.btnrow{display:flex;gap:9px;flex-wrap:wrap;margin-top:16px}
.bh-modal .icon-btn{background:none;border:0;color:var(--muted);cursor:pointer;font-size:calc(20px * var(--font-scale,1));
  line-height:1;padding:4px 7px;border-radius:6px}
.bh-modal .icon-btn:hover{color:var(--ink);background:var(--line)}

/* ---------- sonuç paneli ---------- */
.price-label{font-size:calc(13px * var(--font-scale,1));color:var(--muted);margin:13px 0 0}
.price-label:first-child{margin-top:0}
.p-main{font-size:calc(38px * var(--font-scale,1));font-weight:700;letter-spacing:-.035em;margin:0;line-height:1.1}
.p-alt{font-size:calc(23px * var(--font-scale,1));font-weight:600;letter-spacing:-.02em;margin:0;line-height:1.25}
.p-alt em{font-style:normal;font-size:calc(14px * var(--font-scale,1));font-weight:500;color:var(--muted);margin-inline-start:4px}

.stackrow{display:flex;gap:16px;margin:18px 0 2px}
.stack{display:flex;flex-direction:column-reverse;gap:2px;width:48px;flex:none}
.stack i{height:5px;border-radius:1px;background:var(--line);display:block;transition:background-color .18s}
.legend{flex:1;display:flex;flex-direction:column;justify-content:center;gap:8px}
.leg{display:grid;grid-template-columns:10px 1fr auto;gap:9px;align-items:baseline;font-size:calc(14px * var(--font-scale,1))}
.leg.zero{opacity:.38}
.leg i{width:10px;height:10px;border-radius:2px;transform:translateY(1px)}
.leg span{color:var(--muted)}
.leg b{font-weight:600}

.totals{border-top:1px solid var(--line);margin-top:16px;padding-top:13px}
.trow{display:flex;justify-content:space-between;gap:12px;font-size:calc(14px * var(--font-scale,1));padding:4px 0}
.trow span{color:var(--muted)}
.trow.strong{font-weight:600;font-size:calc(15px * var(--font-scale,1))}
.trow.strong span{color:var(--ink)}
.note{margin-top:15px;font-size:calc(13px * var(--font-scale,1));color:var(--muted);line-height:1.5}

/* ---------- listeler ve tablolar ---------- */
.toolbar{display:flex;gap:9px;flex-wrap:wrap;align-items:center;margin-bottom:14px}
.toolbar .inp{flex:1;min-width:150px}
.toolbar .inp.narrow{flex:0 0 150px}

.tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--r)}
table{width:100%;border-collapse:collapse;font-size:calc(14px * var(--font-scale,1));min-width:620px}
th,td{text-align:start;padding:10px 12px;border-bottom:1px solid var(--line)}
th{background:var(--panel2);color:var(--muted);font-weight:500;font-size:calc(13px * var(--font-scale,1));
  position:sticky;top:0;white-space:nowrap}
tr:last-child td{border-bottom:0}
tbody tr:hover{background:var(--accent-soft)}
td.num,th.num{text-align:end;white-space:nowrap}
td.act{text-align:end;white-space:nowrap;width:1%}

.pill{display:inline-block;padding:2px 9px;border-radius:999px;font-size:calc(12.5px * var(--font-scale,1));
  border:1px solid var(--line2);color:var(--muted);white-space:nowrap}
.pill.paid{color:var(--ok-text);border-color:var(--ok-line)}
.pill.pending{color:var(--warn-text);border-color:var(--warn-line)}
.pill.deposit{color:var(--power);border-color:#6C9BF066}
.pill.cancelled{color:var(--danger-text);border-color:var(--danger-line)}
.pill.failed{color:var(--danger-text);border-color:var(--danger-line)}

.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:14px}
.cards>.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:16px}
.cards>.card h3{margin-bottom:3px}
.card .cardsub{color:var(--muted);font-size:calc(13px * var(--font-scale,1));margin-bottom:12px}
.kv{display:flex;justify-content:space-between;gap:10px;font-size:calc(14px * var(--font-scale,1));padding:4px 0}
.kv span{color:var(--muted)}
.kv b{font-weight:600}

.empty{color:var(--muted);font-size:calc(14px * var(--font-scale,1));padding:26px 4px;text-align:center}

.statrow{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:16px}
.stat{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}
.stat em{font-style:normal;display:block;color:var(--muted);font-size:calc(13px * var(--font-scale,1));margin-bottom:3px}
.stat b{font-size:calc(21px * var(--font-scale,1));font-weight:700;letter-spacing:-.02em}

/* liste satırı (kategoriler, stok) */
.rows{display:flex;flex-direction:column;gap:7px}
.row{display:flex;align-items:center;gap:11px;background:var(--panel2);
  border:1px solid var(--line);border-radius:var(--r-s);padding:9px 12px}
