  /* ---------- Firebase (REST) çağrıları Kullanım Limitleri kartında sayılır ---------- */
  try { FC.usage.wrapFetch(); } catch (e) { }

  /* ---------- sürüm notları ("neler yeni" + latest.json ile aynı: release-notes.json) ---------- */
  var NEWS = {
